from scipy.optimize import least_squares
A=df['A'].values; t=df['t'].values; r=df['dA_dt'].values
def m1(p):
    a0,a1,a2,b=p
    return np.exp(-b*t)*(a0+a1*A+a2*A**2)
def m2(p):
    a0,a1,a2,b=p
    return (a0+a1*A+a2*A**2)/(1+b*t)
def m3(p):
    a0,a1,a2,b=p
    return a0+a1*A+a2*A**2 - b*t*A
for f in [m1,m2,m3]:
    best=None
    for s in range(20):
        p0=np.random.RandomState(s).randn(4)
        res=least_squares(lambda p: f(p)-r, p0)
        if best is None or res.cost<best.cost: best=res
    print(f.__name__, np.round(best.x,5), 'nmse', np.mean((f(best.x)-r)**2)/np.var(r))

